update appointment_leads set latest_draft = coalesce(nullif($3,''),latest_draft), status = case when status in ('booked','suppressed') then status else 'needs_review' end, attention_reason = $4, updated_at = now() where client_slug = 'example-client' and email = lower(trim($1));
